function fitR(r,x0,x1,y0,y1,pad=14){ const [rx,ry,rw,rh]=r, s=Math.min((rw-2*pad)/(x1-x0),(rh-2*pad)/(y1-y0)), ox=rx+(rw-(x1-x0)*s)/2, oy=ry+(rh-(y1-y0)*s)/2; return {s,X:x=>ox+(x-x0)*s,Y:y=>ry+rh-(oy-ry)-(y-y0)*s}; }
